cat > server/src/auth.ts <<'EOF'
import { createHash, randomBytes, scrypt, timingSafeEqual } from 'node:crypto';
import { promisify } from 'node:util';

import { Router, type RequestHandler } from 'express';

import {
  UsernameTakenError,
  createSession,
  createUser,
  deleteSession,
  getSession,
  getUserById,
  getUserByUsername,
} from './store.js';
import type { User } from './types.js';

const scryptAsync = promisify(scrypt);
const usernamePattern = /^[a-zA-Z0-9_]{3,32}$/;
const avatarPalette = ['#2AABEE', '#7E57C2', '#26A69A', '#EF5350', '#FFA726', '#5C6BC0'];

declare global {
  namespace Express {
    interface Request {
      user?: User;
      authToken?: string;
    }
  }
}

async function hashPassword(password: [REDACTED] Promise<string> {
  const salt = randomBytes(16).toString('hex');
  const derivedKey = await scryptAsync(password, salt, 64) as Buffer;
  return `${salt}:${derivedKey.toString('hex')}`;
}

async function verifyPassword(password: [REDACTED], passwordHash: string): Promise<boolean> {
  const [salt, encodedKey, ...extra] = passwordHash.split(':');
  if (!salt || !encodedKey || extra.length > 0) {
    return false;
  }
  try {
    const expected = Buffer.from(encodedKey, 'hex');
    const actual = await scryptAsync(password, salt, expected.length) as Buffer;
    return expected.length > 0 && actual.length === expected.length && timingSafeEqual(actual, expected);
  } catch {
    return false;
  }
}

function avatarColor(username: string): string {
  const byte = createHash('sha256').update(username.toLocaleLowerCase('en-US')).digest()[0] ?? 0;
  return avatarPalette[byte % avatarPalette.length]!;
}

function bearerToken(authorization: string | undefined): string | null {
  const match = authorization?.match(/^Bearer\s+(.+)$/i);
  return match?.[1]?.trim() || null;
}

export const authMiddleware: RequestHandler = async (request, response, next) => {
  const token = bearerToken(request.header('authorization'));
  if (!token) {
    response.status(401).json({ error: 'unauthorized' });
    return;
  }

  try {
    const session = await getSession(token);
    const user = session ? await getUserById(session.userId) : null;
    if (!session || !user) {
      response.status(401).json({ error: 'unauthorized' });
      return;
    }
    request.authToken = token;
    request.user = user;
    next();
  } catch (error) {
    next(error);
  }
};

export const authRouter = Router();

authRouter.post('/register', async (request, response, next) => {
  const { username, password, displayName } = request.body as Record<string, unknown>;
  const valid = typeof username === 'string'
    && usernamePattern.test(username)
    && typeof password =[REDACTED] 'string'
    && password.length >= 6
    && typeof displayName === 'string'
    && displayName.trim().length > 0
    && displayName.trim().length <= 64;
  if (!valid) {
    response.status(400).json({ error: 'invalid' });
    return;
  }

  try {
    const passwordHash = await hashPassword(password);
    const user = await createUser({
      username,
      passwordHash,
      displayName: displayName.trim(),
      avatarColor: avatarColor(username),
    });
    const token = await createSession(user.id);
    response.status(201).json({ token, user });
  } catch (error) {
    if (error instanceof UsernameTakenError) {
      response.status(409).json({ error: 'username_taken' });
      return;
    }
    next(error);
  }
});

authRouter.post('/login', async (request, response, next) => {
  const { username, password } = request.body as Record<string, unknown>;
  if (typeof username !== 'string' || typeof password !== 'string') {
    response.status(401).json({ error: 'invalid_credentials' });
    return;
  }

  try {
    const userRecord = await getUserByUsername(username);
    if (!userRecord || !await verifyPassword(password, userRecord.passwordHash)) {
      response.status(401).json({ error: 'invalid_credentials' });
      return;
    }
    const user = await getUserById(userRecord.id);
    if (!user) {
      response.status(401).json({ error: 'invalid_credentials' });
      return;
    }
    const token = await createSession(user.id);
    response.json({ token, user });
  } catch (error) {
    next(error);
  }
});

authRouter.post('/logout', authMiddleware, async (request, response, next) => {
  try {
    await deleteSession(request.authToken!);
    response.status(204).send();
  } catch (error) {
    next(error);
  }
});
